import json
baseline = json.load(open('baseline-packages.json'))
after = json.load(open('after-cpm-packages.json'))

def extract(data):
    pkgs = {}
    for p in data['projects']:
        name = p['path'].split('/')[-1]
        for fw in p['frameworks']:
            for pkg in fw['topLevelPackages']:
                key = (name, fw['framework'], pkg['id'])
                pkgs[key] = pkg['resolvedVersion']
    return pkgs

b = extract(baseline)
a = extract(after)
all_keys = sorted(set(b.keys()) | set(a.keys()))

changes = []
unchanged = []
for k in all_keys:
    bv = b.get(k)
    av = a.get(k)
    if bv != av:
        changes.append((k[0], k[2], k[1], bv or 'N/A', av or 'N/A'))
    else:
        unchanged.append((k[0], k[2], k[1], bv))

print('CHANGES:')
for c in changes:
    print(f'  {c[0]:20} {c[1]:50} {c[2]:12} {c[3]:10} -> {c[4]}')
print(f'\nUNCHANGED: {len(unchanged)} packages')
"

